\usetikzlibrary{calc}
\begin{tikzpicture}[x=30mm,y=30mm,draw=black,text=black,line width=0.8pt,font=\fontsize{10}{12}\selectfont]
\special{dvisvgm:raw <metadata data-graph-strokes="1"/>}
\definecolor{constructionRed}{HTML}{EF6068}
\coordinate (A) at (0,0);
\coordinate (B) at (1,0);
\coordinate (C) at (1,1);
\coordinate (D) at (0.5,{1+sqrt(3)/2});
\coordinate (E) at (0,1);
\draw (A)--(B)--(C)--(D)--(E)--cycle;
\foreach \P/\Q in {A/B,B/C,C/D,D/E,E/A}{\draw[line width=0.4pt] ($(\P)!0.5!(\Q)!1.2mm!90:(\Q)$)--($(\P)!0.5!(\Q)!1.2mm!-90:(\Q)$);}
\coordinate (AU) at ($(A)!3mm!(E)$);
\coordinate (AV) at ($(A)!3mm!(B)$);
\coordinate (BU) at ($(B)!3mm!(C)$);
\coordinate (BV) at ($(B)!3mm!(A)$);
\draw[line width=0.4pt] (AU)--($(AU)+(AV)-(A)$)--(AV);
\draw[line width=0.4pt] (BU)--($(BU)+(BV)-(B)$)--(BV);
\draw[constructionRed,dashed,line width=0.4pt] (D)--(A) (D)--(B);
\node[anchor=north,inner sep=0.5pt] at ($(D)!8mm!($(A)!0.5!(B)$)$) {$x^{\circ}$};
\end{tikzpicture}

